def seed(folder: Path = ROOT/'notes') -> int:
    folder.mkdir(parents=True,exist_ok=True)
    # Existing personal notes must never be overwritten or mixed with samples.
    if any(folder.rglob('*.md')):
        return 0
    count=0
    for category,items in SUBJECTS.items():
        sub=folder/category
        sub.mkdir(parents=True,exist_ok=True)
        for title,body in items:
            (sub/(title+'.md')).write_text('# '+title+'\n\n'+body+'\n','utf-8')
            count+=1
    return count

if __name__=='__main__':
    print('Created',seed(),'Persian sample notes')
